using System;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
internal sealed partial class Studio{
 readonly Dictionary<string,Form> appearanceForms=new Dictionary<string,Form>();int editingAppearance=-1;
 void AddAppearanceSelector(Panel header){editingAppearance=AppearanceProfiles.Mode;AppearanceProfiles.EditingMode=editingAppearance;var pick=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Location=new Point(580,20),Size=new Size(310,30)};pick.Items.AddRange(new object[]{"编辑浅色配置 · 微信自动跟随","编辑深色配置 · 微信自动跟随"});pick.SelectedIndex=editingAppearance;header.Controls.Add(pick);pick.BringToFront();header.SizeChanged+=delegate{pick.Left=Math.Max(230,header.ClientSize.Width-334);workspaceTitle.Width=Math.Max(190,pick.Left-40);};pick.SelectedIndexChanged+=delegate{if(workspaceBusy||workspaceForms.Exists(WorkspaceFormBusy)){pick.SelectedIndex=editingAppearance;return;}ChangeEditingAppearance(pick.SelectedIndex);};}
 void HoldAppearanceForm(string key,Form form){if(form==null||form.IsDisposed)return;appearanceForms[key+":"+editingAppearance]=form;if(form.Parent!=null)form.Parent.Controls.Remove(form);form.Hide();}
 T RecallAppearanceForm<T>(string key)where T:Form{Form value;if(!appearanceForms.TryGetValue(key+":"+editingAppearance,out value)||value.IsDisposed)return null;var page=workspacePages[key];page.Controls.Add(value);value.Show();return (T)value;}
 void ChangeEditingAppearance(int next){if(next==editingAppearance)return;if(workspaceForms.Exists(WorkspaceFormBusy)){status.Text="请等待当前操作完成，再切换配置。";return;}HoldAppearanceForm("messages",workspaceInk);HoldAppearanceForm("icons",workspaceIcons);HoldAppearanceForm("input",workspaceInput);HoldAppearanceForm("wallpaper",workspaceEffects);editingAppearance=next;AppearanceProfiles.EditingMode=next;workspaceInk=RecallAppearanceForm<InkDialog>("messages");workspaceIcons=RecallAppearanceForm<IconDialog>("icons");workspaceInput=RecallAppearanceForm<InputDialog>("input");workspaceEffects=RecallAppearanceForm<EffectsDialog>("wallpaper");mode.SelectedIndex=next;SelectWorkspace(workspacePage);status.Text="正在编辑"+(next==0?"浅色":"深色")+"配置；未应用的本页草稿会分别保留。后台仍按微信实际外观运行。";}
}
